-- A per-row volatile default makes 18.6 rewrite the table and build the column's index after
-- the rewrite, so the CHECK each rewritten row meets comes first: `23514`, where the
-- constant default of `add_column_unique_default_before_check_loud` is the build's `54000`.
-- @setup
CREATE TABLE t (id int);
INSERT INTO t VALUES (1), (2);
-- @test
-- @expect-error: the rewrite's CHECK before the index build
-- @expect-message
-- @profile-lock
ALTER TABLE t ADD COLUMN c text UNIQUE CHECK (length(c) < 10) DEFAULT (gen_random_uuid()::text || '');
